function draw() {
  // === Variant 5: Symmetric Kaleidoscope Portal ===
  // Applying kaleidoscope coordinate distortion
  uM_rot = frameCount * 0.005;
  push();
  translate(width/2, height/2);
  rotate(uM_rot);
  scale(1.1);
  translate(-width/2, -height/2);

   randomSeed(num);
