function circlePacking() {
	noStroke();
	fill(51)
	push();
	let points = [];
	let count = 10000;
	for (let i = 0; i < count; i++) {
		let s = random(15,200);
		let x = random(width);
		let y = random(height);
		let add = true;
		for (let j = 0; j < points.length; j++) {
			let p = points[j];
			if (dist(x, y, p.x, p.y) < (s + p.z) * 0.6) {
				add = false;
				break;
			}
		}
		if (add) points.push(createVector(x, y, s));
	}
	for (let i = 0; i < points.length; i++) {
		let p = points[i];
		push();
		translate(p.x, p.y);
		let r = p.z;
		noStroke();
		push();

		fill(random(["#c9e6ee", "#faeee5", "#fad1d8", "#f2c4d6"," #dbc0e7"]))
		gradient(r)
		ellipse(0,0,r)
		pop();
		push();
		blendMode(MULTIPLY)
		fill(random(["#c9e6ee", "#faeee5", "#fad1d8", "#f2c4d6"," #dbc0e7"]))
		ellipse(-r*0.05,r*0.05,r)
	pop();
		pop();
	}
}
