function gradient(r) {


	noStroke();
	let gradientFill = drawingContext.createLinearGradient(
		0,
		0,
		r,
		r
	);

	gradientFill.addColorStop(0, color("#c9e6ee",));
	gradientFill.addColorStop(0.25, color("#faeee5"));
	gradientFill.addColorStop(0.5, color("#fad1d8"));
	gradientFill.addColorStop(0.75, color( "#f2c4d6"));
	gradientFill.addColorStop(1, color(" #dbc0e7"));
	drawingContext.fillStyle = gradientFill;
}


